4061|md_analyze_marks(MD_CTX* ctx, const MD_LINE* lines, MD_SIZE n_lines,
4062|                 int mark_beg, int mark_end, const CHAR* mark_chars, unsigned flags)
4063|{
4064|    int i = mark_beg;
4065|    OFF last_end = lines[0].beg;
4066|
4067|    MD_UNUSED(lines);
4068|    MD_UNUSED(n_lines);
4069|
4070|    while(i < mark_end) {
4071|        MD_MARK* mark = &ctx->marks[i];
4072|
4073|        /* Skip resolved spans. */
4074|        if(mark->flags & MD_MARK_RESOLVED) {
4075|            if((mark->flags & MD_MARK_OPENER)  &&
4076|               !((flags & MD_ANALYZE_NOSKIP_EMPH) && ISANYOF_(mark->ch, "*_~")))
4077|            {
4078|                MD_ASSERT(i < mark->next);
4079|                i = mark->next + 1;
4080|            } else {
4081|                i++;
4082|            }
4083|            continue;
4084|        }
4085|
4086|        /* Skip marks we do not want to deal with. */
4087|        if(!ISANYOF_(mark->ch, mark_chars)) {
4088|            i++;
4089|            continue;
4090|        }
4091|
4092|        /* The resolving in previous step could have expanded a mark. */
4093|        if(mark->beg < last_end) {
4094|            i++;
4095|            continue;
4096|        }
4097|
4098|        /* Analyze the mark. */
4099|        switch(mark->ch) {
4100|            case '[':   /* Pass through. */
4101|            case '!':   /* Pass through. */
4102|            case ']':   md_analyze_bracket(ctx, i); break;
4103|            case '&':   md_analyze_entity(ctx, i); break;
4104|            case '_':   /* Pass through. */
4105|            case '*':   md_analyze_emph(ctx, i); break;
4106|            case '~':   md_analyze_tilde(ctx, i); break;
4107|            case '$':   md_analyze_dollar(ctx, i); break;
4108|            case '.':   /* Pass through. */
4109|            case ':':   /* Pass through. */
4110|            case '@':   md_analyze_permissive_autolink(ctx, i); break;
4111|        }
4112|
4113|        if(mark->flags & MD_MARK_RESOLVED) {
4114|            if(mark->flags & MD_MARK_OPENER)
4115|                last_end = ctx->marks[mark->next].end;
4116|            else
4117|                last_end = mark->end;
4118|        }
4119|
4120|        i++;
4121|    }
